 async function loadChunks(force=false){if(loading||!active||!socket?.connected)return;const ownEpoch=epoch,[cx,cz]=C.chunk(position.x,position.z),coords=[];for(let dz=-2;dz<=2;dz++)for(let dx=-2;dx<=2;dx++)if(!chunks.get((cx+dx)+','+(cz+dz))?.ready)coords.push([cx+dx,cz+dz]);for(const[k,c]of chunks)if(Math.abs(c.cx-cx)>2||Math.abs(c.cz-cz)>2){removeChunk(c);chunks.delete(k);}if(!coords.length)return;coords.sort((a,b)=>(a[0]-cx)**2+(a[1]-cz)**2-(b[0]-cx)**2-(b[1]-cz)**2);loading=true;try{const d=await rpc('chunks',{coords});if(epoch!==ownEpoch)return;for(const c of d.chunks){if(epoch!==ownEpoch)return;const terrain=C.generate(c.cx,c.cz,seed);const old=chunks.get(c.cx+','+c.cz);if(old?.ready&&old.revision>c.revision)continue;const blocks=old&&old.revision>c.revision?{...c.blocks,...old.blocks}:c.blocks;chunks.set(c.cx+','+c.cz,{...c,blocks,revision:Math.max(c.revision,old?.revision||0),terrain,ready:true,dirty:true,meshes:old?.meshes||[]});for(const[dx,dz]of [[1,0],[-1,0],[0,1],[0,-1]])dirty(c.cx+dx,c.cz+dz);await new Promise(r=>setTimeout(r,0));}}catch(e){message(e.message);}finally{if(epoch===ownEpoch)loading=false;}}
