 function itemSlot(id,count,parent,action,cls=''){const button=el('button',null,parent,'vx-item-slot '+cls);button.title=(C.items[id]?.name||'Пусто')+(count?' ×'+count:'');button.setAttribute('aria-label',C.items[id]?.name||'Пустой слот');if(id){icon(id,button);if(count)el('b',count,button,'vx-item-count');if(C.items[id]?.durability){const progress=el('span',null,button,'vx-wear');progress.style.setProperty('--wear',100*(wear[id]??C.items[id].durability)/C.items[id].durability+'%');}}else el('span','·',button);button.onclick=action;return button;}
 function updateBar(){hotbar.replaceChildren();const available=Object.keys(bag).map(Number).filter(id=>(C.blocks[id]||C.items[id]?.kind||C.items[id]?.food||id===121||id===130||id===131)&&bag[id]>0&&id!==12&&id!==13);if(!barSlots.some(Boolean))available.slice(0,9).forEach((id,i)=>barSlots[i]=id);if(selected&&bag[selected]>0){const index=barSlots.indexOf(selected);if(index>=0)activeSlot=index;else barSlots[activeSlot]=selected;}barSlots.forEach((id,index)=>{const button=itemSlot(id,bag[id]||0,hotbar,()=>{cancelMining();activeSlot=index;selected=id;updateBar();},'vx-slot'+(index===activeSlot?' selected':'')+(!(bag[id]>0)?' empty':''));el('small',index+1,button,'vx-slot-key');button.dataset.block=id;});}
