   const pager=el('div',null,parent,'vx-inv-tabs'),prev=el('button','‹',pager),info=el('small','',pager),next=el('button','›',pager),list=el('div',null,parent,'vx-recipes');let page=0;
   function draw(){const q=input.value.trim().toLowerCase(),hits=entries.filter(e=>!q||(e.name+' '+(e.key||e.id)).toLowerCase().includes(q));page=Math.max(0,Math.min(page,Math.ceil(hits.length/18)-1));list.replaceChildren();hits.slice(page*18,page*18+18).forEach(e=>paint(e,list));info.textContent=hits.length?' '+(page+1)+' / '+Math.ceil(hits.length/18)+' · '+hits.length+' ': 'Ничего не найдено';prev.disabled=!page;next.disabled=(page+1)*18>=hits.length;}
