   browse(panel,entries,(b,list)=>{const card=el('div',null,list,'vx-recipe');icon(b.id,card);el('strong',b.name,card);el('small',b.key,card);const spec=C.blocks[b.id];if(!owner||!spec?.color||spec.unbreakable||C.fluid(b.id)||[26,27,28].includes(b.id))return;
     const btn=el('button','Получить ×64',card);btn.onclick=async()=>{btn.disabled=true;try{const d=await rpc('palette',{id:b.id});bag=d.inventory;updateBar();if(token===panelToken)message('В рюкзаке: '+b.name+' ×'+(bag[b.id]||0));}catch(e){message(e.message);}finally{btn.disabled=false;}};
   },'Поиск блока по названию или ID');
