  const search=el('input',null,center,'vx-item-search');search.placeholder='Найти предмет…';search.setAttribute('aria-label','Найти предмет');const tabs=el('div',null,center,'vx-inv-tabs'),inv=el('div',null,center,'vx-inventory');
